import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testMixedAlliances() {
        val result = countByAlliance(listOf("Red", "Blue", "Red"))
        Assert.assertEquals(2, result["Red"])
        Assert.assertEquals(1, result["Blue"])
    }

    @Test
    fun testAllSameColor() {
        val result = countByAlliance(listOf("Red", "Red", "Red"))
        Assert.assertEquals(3, result["Red"])
        Assert.assertNull(result["Blue"])
    }

    @Test
    fun testEmptyList() {
        val result = countByAlliance(listOf())
        Assert.assertTrue(result.isEmpty())
    }

    @Test
    fun testEqualCounts() {
        val result = countByAlliance(listOf("Red", "Blue", "Red", "Blue"))
        Assert.assertEquals(2, result["Red"])
        Assert.assertEquals(2, result["Blue"])
    }
}
